 if exists(select 1 from auth.users u join demo_fixture_data d on u.email='costep-demo-'||d.n::text||'@example.invalid' where u.id<>d.id) then
  raise exception 'demo_email_collision';
 end if;
end $$;
insert into auth.users(id,email,raw_user_meta_data,banned_until)
select id,'costep-demo-'||n::text||'@example.invalid',jsonb_build_object('costep_demo_batch','timeline-demo-20261017-v1'),'9999-12-31'::timestamptz
from demo_fixture_data on conflict(id) do nothing;
insert into private.demo_seed_users(user_id,batch) select id,'timeline-demo-20261017-v1' from demo_fixture_data on conflict(user_id) do nothing;
update public.profiles p set display_name=d.name,bio='架空ユーザーです。タイムラインとおすすめの表示確認用です。',
 learning_fields=d.fields,field=d.fields->0->>'field',level=coalesce((d.fields->0->>'level')::integer,0),goals=d.goals,goal='',recommend=d.recommend
from demo_fixture_data d where p.id=d.id;
update private.preferences p set visibility=d.visibility,dm_policy='mutual',profile_completed=true from demo_fixture_data d where p.id=d.id;
insert into public.posts(id,owner_id,body,created_at)
select ('de000002-0000-4000-8000-'||lpad(((d.n-1)*2+j)::text,12,'0'))::uuid,d.id,
'【デモ・架空 '||d.code||'-'||j||'】'||d.body||case when j=2 then ' これは2件目の表示確認用の投稿です。' else '' end,
now()-make_interval(mins=>d.n*3+j)
from demo_fixture_data d cross join generate_series(1,2) j on conflict(id) do nothing;
insert into public.study_records(id,owner_id,field,study_date,minutes,request_id)
select ('de000003-0000-4000-8000-'||lpad(((d.n-1)*2+j)::text,12,'0'))::uuid,d.id,d.fields->0->>'field',current_date-j+1,30+j*15,
('de000004-0000-4000-8000-'||lpad(((d.n-1)*2+j)::text,12,'0'))::uuid
from demo_fixture_data d cross join generate_series(1,2) j on conflict(id) do nothing;
commit;
